function AdvancedAnalysis({ products }: { products: Product[] }) {
  const stats = useMemo(() => {
    const prices = products.map(p => p.price);
    const ratings = products.map(p => p.rating);
    const reviews = products.map(p => p.reviews);

    const calculateStats = (values: number[]) => {
      const sorted = [...values].sort((a, b) => a - b);
      const mean = values.reduce((sum, v) => sum + v, 0) / values.length;
      const median = sorted[Math.floor(sorted.length / 2)];
      const variance = values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length;
      const std = Math.sqrt(variance);
      return { mean, median, std, variance };
    };

    const quantile = (values: number[], q: number) => {
      const sorted = [...values].sort((a, b) => a - b);
      const pos = (sorted.length - 1) * q;
      const base = Math.floor(pos);
      const rest = pos - base;
      if (sorted[base + 1] !== undefined) {
        return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
      }
      return sorted[base];
    };

    const priceStats = {
      ...calculateStats(prices),
      q1: quantile(prices, 0.25),
      q3: quantile(prices, 0.75),
    };

    const ratingStats = calculateStats(ratings);
    const reviewStats = calculateStats(reviews);

    const valueScores = products.map(p => ({
      name: p.name,
      score: (p.rating / p.price) * 100,
    }));
    const sortedByValue = [...valueScores].sort((a, b) => b.score - a.score);

    return { priceStats, ratingStats, reviewStats, sortedByValue };
  }, [products]);

  const { priceStats, ratingStats, reviewStats, sortedByValue } = stats;

